import { useState } from 'react';
import { trace, useSnapshot } from '@observatory/lab';

export default function App() {
  const [count, setCount] = useState(0);
  const [waiting, setWaiting] = useState(false);
  useSnapshot('Counter', { count, waiting });
  function later() {
    trace.action('Отложить', { captured: count });
    setWaiting(true);
    setTimeout(() => {
      trace.effect('Timer', 'Таймер сработал', { captured: count });
      setCount(count + 1);
      setWaiting(false);
    }, 2000);
  }
  return (
    <section>
      <span className="eyebrow">Замыкание</span>
      <h1>{count}</h1>
      <p>
        {waiting
          ? 'Таймер запущен. Нажмите «+1 сейчас».'
          : 'Отложите обновление, затем увеличьте значение.'}
      </p>
      <button disabled={waiting} onClick={later}>
        +1 через 2 секунды
      </button>
      <button
        className="secondary"
        onClick={() => {
          trace.action('Сейчас');
          setCount((n) => n + 1);
        }}
      >
        +1 сейчас
      </button>
    </section>
  );
}
